/**
 * Bookings display settings — one row per (site × app × widget type).
 * Owned by Bookings.
 *
 * Shared/common settings for Wix-curated widgets live in typed proto fields
 * (widget_settings). App-specific settings (and all third-party widget settings)
 * live under extended_fields, each app registering its own JSON Schema in Dev
 * Center against this entity's FQDN.
 */
export interface BookingsDisplaySettings
  extends BookingsDisplaySettingsWidgetSettingsOneOf {
  sidePanelView?: SidePanelView;
  /**
   * The BookingsDisplaySettings id. Opaque and server-assigned (derived deterministically
   * from the natural key app_id + widget_type [+ custom_widget_key]); clients treat it as
   * opaque and address rows by the natural key, never by id.
   * A default row that has never been saved carries no `id`.
   * @format GUID
   * @readonly
   */
  id?: string | null;
  /**
   * Revision number, server-assigned, which increments by 1 each time the row is
   * updated. Read-only: clients never set it (Upsert ignores any supplied value).
   * A never-saved row returned by GetBookingsDisplaySettingsByWidget (synthesised
   * defaults) has no `revision`.
   * @readonly
   */
  revision?: string | null;
  /**
   * Date and time the row was created.
   * @readonly
   */
  createdDate?: Date | null;
  /**
   * Date and time the row was last updated.
   * @readonly
   */
  updatedDate?: Date | null;
  /**
   * ID of the app this settings row belongs to. Client-supplied; part of the
   * composite key. (The site is implicit via SDL tenancy.)
   * Required-ness enforced at the Upsert method level.
   * @format GUID
   */
  appId?: string;
  /**
   * Widget type. Client-supplied; part of the composite key.
   * Wix-curated widgets use a typed enum value (e.g. SIDE_PANEL_VIEW).
   * Third-party widgets use CUSTOM + custom_widget_key.
   */
  widgetType?: WidgetTypeWithLiterals;
  /**
   * Third-party widget identifier. Required only when `widget_type` is
   * `CUSTOM`; otherwise leave it empty. Together with `app_id` it
   * identifies a third-party widget's settings row.
   * @maxLength 90
   */
  customWidgetKey?: string;
  /**
   * Custom field data for the `BookingsDisplaySettings` row.
   * [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields)
   * must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
}

/** @oneof */
export interface BookingsDisplaySettingsWidgetSettingsOneOf {
  sidePanelView?: SidePanelView;
}

/** Identifies the widget a BookingsDisplaySettings row applies to. */
export enum WidgetType {
  SIDE_PANEL_VIEW = 'SIDE_PANEL_VIEW',
  /** Third-party widget; identifier carried in custom_widget_key. */
  CUSTOM = 'CUSTOM',
}

/** @enumType */
export type WidgetTypeWithLiterals = WidgetType | 'SIDE_PANEL_VIEW' | 'CUSTOM';

/**
 * Display settings for the side panel's **view** mode — the read-only panel shown for a
 * booked item (an appointment or class session, or a course), openable from the calendar
 * and other surfaces. These settings govern the view mode only; the panel's edit mode is
 * unaffected. All sections are typed fields on the entity. Apps can still attach their own
 * custom fields via Data Extensions (`extended_fields`).
 */
export interface SidePanelView {
  /** Notes section. */
  notes?: NotesSection;
  /** Price section. */
  price?: PriceSection;
  /** Location section. */
  location?: LocationSection;
  /** Assigned staff member section. */
  assignedStaffMember?: AssignedStaffMemberSection;
  /** Requested staff member method section. */
  requestedStaffMemberMethod?: RequestedStaffMemberMethodSection;
  /** Resources section. */
  resources?: ResourcesSection;
  /** Add-ons section. */
  addOns?: AddOnsSection;
}

export interface NotesSection {
  /**
   * Whether the notes section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
  /** How the notes content is rendered. Defaults to `TOOLTIP` when not set. */
  displayMode?: NotesDisplayModeWithLiterals;
}

export enum NotesDisplayMode {
  TOOLTIP = 'TOOLTIP',
  INLINE = 'INLINE',
}

/** @enumType */
export type NotesDisplayModeWithLiterals =
  | NotesDisplayMode
  | 'TOOLTIP'
  | 'INLINE';

export interface PriceSection {
  /**
   * Whether the price section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
}

export interface LocationSection {
  /**
   * Whether the location section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
}

export interface AssignedStaffMemberSection {
  /**
   * Whether the assigned-staff-member section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
}

/**
 * How the staff member for a booking was requested — for example, a specific
 * member the customer chose, or automatic assignment when the customer had no
 * preference. This section shows that information in the side panel.
 */
export interface RequestedStaffMemberMethodSection {
  /**
   * Whether the requested-staff-member-method section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
}

/**
 * Resources (such as rooms or equipment) assigned to the booking. This section
 * shows those resources in the side panel.
 */
export interface ResourcesSection {
  /**
   * Whether the resources section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
}

/**
 * Optional add-ons (extra services or items) attached to the booking. This
 * section shows those add-ons in the side panel.
 */
export interface AddOnsSection {
  /**
   * Whether the add-ons section is visible. Defaults to `true` when not set.
   * On Upsert, omit to leave the stored value unchanged.
   */
  visible?: boolean | null;
}

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

export interface GetBookingsDisplaySettingsByWidgetRequest {
  /**
   * ID of the app whose widget settings to read. Part of the natural key.
   * (The site is implicit via SDL tenancy.) Required (enforced at the method level).
   * @format GUID
   */
  appId: string;
  /**
   * Widget type to read. Part of the natural key. Wix-curated widgets use a typed
   * enum value (e.g. SIDE_PANEL_VIEW); third-party widgets use CUSTOM
   * together with `custom_widget_key`. Required (enforced at the method level).
   */
  widgetType: WidgetTypeWithLiterals;
  /**
   * Third-party widget identifier. Required when `widget_type` is CUSTOM; must be
   * empty otherwise. Together with `app_id` it identifies a third-party widget's
   * settings row. Passed as a query parameter (not a path segment), so it may
   * contain any characters up to the length limit.
   * @maxLength 90
   */
  customWidgetKey?: string;
}

export interface GetBookingsDisplaySettingsByWidgetResponse {
  /**
   * The widget's settings row, with defaults backfilled per field. Never empty:
   * a synthesised, fully defaulted row (with no `revision`) is returned when
   * nothing has been saved for the widget.
   */
  bookingsDisplaySettings?: BookingsDisplaySettings;
}

export interface UpsertBookingsDisplaySettingsRequest {
  /**
   * Entity payload. Required: `app_id`, `widget_type` (+ `custom_widget_key`
   * when `widget_type = CUSTOM`), and at least one of `widget_settings` /
   * `extended_fields`. `revision` is server-assigned and read-only; any value
   * set here is ignored.
   */
  bookingsDisplaySettings: BookingsDisplaySettings;
  /**
   * Optional. You don't need to set this — it's inferred from the fields you
   * include in the payload.
   * @internal
   */
  fieldMask?: string[];
}

export interface UpsertBookingsDisplaySettingsResponse {
  /** The entity row after the write, defaults backfilled. revision >= 1. */
  bookingsDisplaySettings?: BookingsDisplaySettings;
}

export interface DeleteBookingsDisplaySettingsRequest {
  /**
   * ID of the BookingsDisplaySettings row to delete. Obtain it from a previous
   * UpsertBookingsDisplaySettings response, or from a
   * GetBookingsDisplaySettingsByWidget response for a saved row (a synthesised
   * default row carries no `id`).
   * @format GUID
   */
  bookingsDisplaySettingsId: string;
}

export interface DeleteBookingsDisplaySettingsResponse {}

export interface DomainEvent extends DomainEventBodyOneOf {
  createdEvent?: EntityCreatedEvent;
  updatedEvent?: EntityUpdatedEvent;
  deletedEvent?: EntityDeletedEvent;
  actionEvent?: ActionEvent;
  /** Event ID. With this ID you can easily spot duplicated events and ignore them. */
  id?: string;
  /**
   * Fully Qualified Domain Name of an entity. This is a unique identifier assigned to the API main business entities.
   * For example, `wix.stores.catalog.product`, `wix.bookings.session`, `wix.payments.transaction`.
   */
  entityFqdn?: string;
  /**
   * Event action name, placed at the top level to make it easier for users to dispatch messages.
   * For example: `created`/`updated`/`deleted`/`started`/`completed`/`email_opened`.
   */
  slug?: string;
  /** ID of the entity associated with the event. */
  entityId?: string;
  /** Event timestamp in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601) format and UTC time. For example, `2020-04-26T13:57:50.699Z`. */
  eventTime?: Date | null;
  /**
   * Whether the event was triggered as a result of a privacy regulation application
   * (for example, GDPR).
   */
  triggeredByAnonymizeRequest?: boolean | null;
  /** If present, indicates the action that triggered the event. */
  originatedFrom?: string | null;
  /**
   * A sequence number that indicates the order of updates to an entity. For example, if an entity was updated at `16:00` and then again at `16:01`, the second update will always have a higher sequence number.
   * You can use this number to make sure you're handling updates in the right order. Just save the latest sequence number on your end and compare it to the one in each new message. If the new message has an older (lower) number, you can safely ignore it.
   */
  entityEventSequence?: string | null;
}

/** @oneof */
export interface DomainEventBodyOneOf {
  createdEvent?: EntityCreatedEvent;
  updatedEvent?: EntityUpdatedEvent;
  deletedEvent?: EntityDeletedEvent;
  actionEvent?: ActionEvent;
}

export interface EntityCreatedEvent {
  entityAsJson?: string;
  /**
   * Indicates the event was triggered by a restore-from-trashbin operation for a previously deleted entity
   * @internal
   */
  triggeredByUndelete?: boolean | null;
  /** Indicates the event was triggered by a restore-from-trashbin operation for a previously deleted entity */
  restoreInfo?: RestoreInfo;
  /**
   * Optional domain-specific metadata defined by the API owner, encoded as JSON.
   * @internal
   */
  additionalMetadataAsJson?: string | null;
}

export interface RestoreInfo {
  deletedDate?: Date | null;
}

export interface EntityUpdatedEvent {
  /**
   * Since platformized APIs only expose PATCH and not PUT we can't assume that the fields sent from the client are the actual diff.
   * This means that to generate a list of changed fields (as opposed to sent fields) one needs to traverse both objects.
   * We don't want to impose this on all developers and so we leave this traversal to the notification recipients which need it.
   */
  currentEntityAsJson?: string;
  /**
   * This field is currently part of the of the EntityUpdatedEvent msg, but scala/node libraries which implements the domain events standard
   * wont populate it / have any reference to it in the API.
   * The main reason for it is that fetching the old entity from the DB will have a performance hit on an update operation so unless truly needed,
   * the developer should send only the new (current) entity.
   * An additional reason is not wanting to send this additional entity over the wire (kafka) since in some cases it can be really big
   * Developers that must reflect the old entity will have to implement their own domain event sender mechanism which will follow the DomainEvent proto message.
   * @internal
   * @deprecated
   */
  previousEntityAsJson?: string | null;
  /**
   * Map of fully qualified field paths to their previous values for fields that changed.
   * For more details please see [AIP](https://dev.wix.com/docs/rnd-general/articles/p13n-guidelines-aips/guidance-aips/design-patterns/7016-events#modified-fields-format)
   * @internal
   */
  modifiedFields?: Record<string, any>;
  /**
   * Optional domain-specific metadata defined by the API owner, encoded as JSON.
   * @internal
   */
  additionalMetadataAsJson?: string | null;
}

export interface EntityDeletedEvent {
  /**
   * Indicates if the entity is sent to trash-bin. only available when trash-bin is enabled
   * @internal
   */
  movedToTrash?: boolean | null;
  /** Entity that was deleted. */
  deletedEntityAsJson?: string | null;
  /**
   * Optional domain-specific metadata defined by the API owner, encoded as JSON.
   * @internal
   */
  additionalMetadataAsJson?: string | null;
}

export interface ActionEvent {
  bodyAsJson?: string;
}

export interface MessageEnvelope {
  /**
   * App instance ID.
   * @format GUID
   */
  instanceId?: string | null;
  /**
   * Event type.
   * @maxLength 150
   */
  eventType?: string;
  /** The identification type and identity data. */
  identity?: IdentificationData;
  /** Stringify payload. */
  data?: string;
  /** Details related to the account */
  accountInfo?: AccountInfo;
}

export interface IdentificationData extends IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
  /** @readonly */
  identityType?: WebhookIdentityTypeWithLiterals;
}

/** @oneof */
export interface IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
}

export enum WebhookIdentityType {
  UNKNOWN = 'UNKNOWN',
  ANONYMOUS_VISITOR = 'ANONYMOUS_VISITOR',
  MEMBER = 'MEMBER',
  WIX_USER = 'WIX_USER',
  APP = 'APP',
}

/** @enumType */
export type WebhookIdentityTypeWithLiterals =
  | WebhookIdentityType
  | 'UNKNOWN'
  | 'ANONYMOUS_VISITOR'
  | 'MEMBER'
  | 'WIX_USER'
  | 'APP';

export interface AccountInfo {
  /**
   * ID of the Wix account associated with the event.
   * @format GUID
   */
  accountId?: string | null;
  /**
   * ID of the parent Wix account. Only included when accountId belongs to a child account.
   * @format GUID
   */
  parentAccountId?: string | null;
  /**
   * ID of the Wix site associated with the event. Only included when the event is tied to a specific site.
   * @format GUID
   */
  siteId?: string | null;
}

/** @docsIgnore */
export type UpsertBookingsDisplaySettingsApplicationErrors = {
  code?: 'INVALID_EXTENDED_FIELDS';
  description?: string;
  data?: Record<string, any>;
};
